-- Data for db_label — the system UI dictionary.
--
-- `db_label` translates the *application* (button captions, column headings,
-- page titles, status chips, error wording); the `db_*_label` tables translate
-- *records*. Every string the Leptos front end renders is looked up here as
-- "<category>.<key>", so adding a language means seeding rows in this table —
-- no rebuild of the WASM bundle.
--
-- Language ids come from 02_db_language_data.sql:
--   th = 019ca1eb-21c0-7000-8001-000000000001
--   en = 019ca1eb-21c0-7000-8002-000000000002
--
-- Ids are UUIDv7 with a readable suffix so a row can be found by eye during
-- development; regenerate properly if this table is ever managed by the app.

-- Load Thai and English side by side from one VALUES list, so a missing
-- translation is visible as a gap in the diff rather than in production.
INSERT INTO "db_label" ("id", "language_id", "category", "key", "value") VALUES

